use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0].clone()
        if cmd == "balance" {
            let n = p[1].clone()
            if acc.contains_key(n) {
                println("${acc.get(n).unwrap_or(0)}")
            } else {
                println("error: unknown account ${n}")
            }
        } else if cmd == "open" {
            let n = p[1].clone()
            let a: int = p[2].parse::<int>().unwrap_or(0)
            if a < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(n) {
                println("error: duplicate account")
            } else {
                acc.insert(n, a)
                println("ok")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let n = p[1].clone()
            let a: int = p[2].parse::<int>().unwrap_or(0)
            if a <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(n) {
                println("error: unknown account ${n}")
            } else {
                let b: int = acc.get(n).unwrap_or(0)
                if cmd == "deposit" {
                    acc.insert(n, b + a)
                    println("ok")
                } else if a > b {
                    println("error: insufficient funds")
                } else {
                    acc.insert(n, b - a)
                    println("ok")
                }
            }
        } else if cmd == "transfer" {
            let f = p[1].clone()
            let t = p[2].clone()
            let a: int = p[3].parse::<int>().unwrap_or(0)
            if a <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(f) {
                println("error: unknown account ${f}")
            } else if !acc.contains_key(t) {
                println("error: unknown account ${t}")
            } else if f == t {
                println("error: same account")
            } else {
                let fb: int = acc.get(f).unwrap_or(0)
                let tb: int = acc.get(t).unwrap_or(0)
                if a > fb {
                    println("error: insufficient funds")
                } else {
                    acc.insert(f, fb - a)
                    acc.insert(t, tb + a)
                    println("ok")
                }
            }
        }
    }
    let mut names: Vec<string> = []
    for k in acc.keys() {
        names.push(k.clone())
    }
    names.sort()
    for n in names {
        println("${n} ${acc.get(n).unwrap_or(0)}")
    }
}

